def apply_transform(grid):
    h, w = len(grid), len(grid[0])

    sep_col = a_w = b_w = sep_row = a_h = b_h = None

    # Check for uniform column separator
    for j in range(w):
        if all(grid[i][j] == grid[0][j] for i in range(1, h)):
            sep_col = j
            a_w, b_w = sep_col, w - sep_col - 1
            if a_w > b_w:
                # Crossed with row separator
                for i in range(h):
                    if all(grid[i][k] == grid[i][0] for k in range(1, w) if k != sep_col):
                        sep_row = i
                        a_h, b_h = sep_row, h - sep_row - 1
                        a_w, b_w = sep_col, w - sep_col - 1
                        break
            else:
                a_h, b_h = h, h
            break

    # Check for uniform row separator
    if sep_col is None:
        for i in range(h):
            if all(grid[i][j] == grid[i][0] for j in range(1, w)):
                sep_row = i
                a_h, b_h = sep_row, h - sep_row - 1
                a_w, b_w = w, w

    if sep_row is not None:
        # Row separator
        A = [row[:a_w] for row in grid[:sep_row]]
        B = [row[a_w+1:] for row in grid[sep_row+1:]]
    else:
        # Column separator
        A = [row[:a_w] for row in grid]
        B = [row[a_w+1:] for row in grid]

    output = []
    for r in range(a_h):
        row = []
        for c in range(a_w):
            if A[r][c] == B[r][c]:
                row.append(3)
            else:
                vals = [A[r][c] for c in range(a_w)] + [B[r][c] for c in range(b_w)]
                counter = Counter(vals)
                bg = counter.most_common(1)[0][0]
                row.append(bg)
        output.append(row)

    return output

